import 'dart:io' as io;
import 'package:salesiq_mobilisten/salesiq_mobilisten.dart';

void init() {
  if (io.Platform.isIOS || io.Platform.isAndroid) {
    String appKey = io.Platform.isIOS ? "IOS_APP_KEY" : "ANDROID_APP_KEY";
    String accessKey = io.Platform.isIOS ? "IOS_ACCESS_KEY" : "ANDROID_ACCESS_KEY";
    var config = SalesIQConfiguration(appKey: appKey, accessKey: accessKey);
    ZohoSalesIQ.initialize(config).then((_) {
      ZohoSalesIQ.launcher.show(VisibilityMode.always);
    });
  }
}
